//! USB enforcement layer (USB-03, USB-04).
//!
//! [`UsbEnforcer`] bridges the Phase 23 drive-letter map ([`UsbDetector`])
//! and the Phase 24 trust-tier cache ([`DeviceRegistryCache`]) to enforce
//! USB device trust tiers at file I/O time.
//!
//! ## Decision logic
//!
//! 1. Extract the drive letter from the file path (first character, must be ASCII alpha).
//! 2. Look up the [`DeviceIdentity`] for that drive letter in the USB detector's map.
//! 3. Look up the [`UsbTrustTier`] from the device registry using the VID/PID/serial.
//! 4. Return a [`UsbBlockResult`] carrying the decision, identity, tier, and toast flag:
//!    - [`UsbTrustTier::Blocked`]: return `None` — device is disabled at the PnP
//!      level by [`DeviceController`](crate::device_controller::DeviceController),
//!      so no file events are expected.
//!    - [`UsbTrustTier::ReadOnly`]: return `None` — volume DACL is modified by
//!      [`DeviceController`](crate::device_controller::DeviceController) on arrival,
//!      so NTFS enforces the restriction.
//!    - [`UsbTrustTier::FullAccess`]: return `None` (fall through to ABAC engine).
//!
//! UNC paths (`\\server\share\...`) are not USB drives and return `None` immediately.
//! Paths on drives not present in the USB detector return `None` (not a USB drive).
//!
//! ## Architecture note (Phase 31)
//!
//! Active blocking (device disable for Blocked, DACL modification for ReadOnly)
//! is now handled by [`DeviceController`](crate::device_controller::DeviceController)
//! firing from `usb_wndproc` on device arrival. This module only handles the
//! fallback case: unregistered devices (unknown VID/PID/serial) still default
//! to deny at the file I/O level as a defence-in-depth measure.

use std::collections::HashMap;
use std::sync::Arc;
use std::time::{Duration, Instant};

use dlp_common::{Decision, DeviceIdentity, UsbTrustTier};
use parking_lot::Mutex;

use crate::detection::UsbDetector;
use crate::device_registry::DeviceRegistryCache;
use crate::interception::FileAction;

/// Result returned by [`UsbEnforcer::check`] when a USB operation is blocked.
///
/// Carries all data needed by the interception event loop to emit an audit event
/// and — when `notify` is true — broadcast a toast notification to the UI.
///
/// `notify` is `false` when a per-drive-letter 30-second cooldown is active.
/// The block decision (`Decision::DENY`) is always applied regardless of `notify`.
#[derive(Debug, Clone, PartialEq)]
pub struct UsbBlockResult {
    /// The enforcement decision — currently always `Decision::DENY`.
    pub decision: Decision,
    /// The device identity for the blocked drive (VID, PID, serial, description).
    pub identity: DeviceIdentity,
    /// The USB trust tier that triggered the block.
    pub tier: UsbTrustTier,
    /// `true` if the UI should display a toast; `false` when cooldown suppresses it.
    pub notify: bool,
    /// Owner SID of the per-user registry entry that determined the tier.
    pub owner_sid: Option<String>,
    /// Owner username of the per-user registry entry that determined the tier.
    pub owner_user: Option<String>,
}

/// Bridges USB device identity (Phase 23) and trust-tier registry (Phase 24)
/// to enforce device trust policies at file I/O time.
///
/// Held behind `Arc` so it can be shared between the event loop and future
/// USB notification handlers without cloning the underlying caches.
pub struct UsbEnforcer {
    detector: Arc<UsbDetector>,
    registry: Arc<DeviceRegistryCache>,
    /// Per-drive-letter timestamp of the last toast broadcast.
    /// Used to enforce the 30-second cooldown (D-02).
    last_toast: Mutex<HashMap<char, Instant>>,
}

impl UsbEnforcer {
    /// Constructs a new [`UsbEnforcer`] backed by the given caches.
    ///
    /// # Arguments
    ///
    /// * `detector` - Shared USB detector holding the drive-letter → [`DeviceIdentity`] map.
    /// * `registry` - Shared device registry cache holding VID/PID/serial → [`UsbTrustTier`].
    pub fn new(detector: Arc<UsbDetector>, registry: Arc<DeviceRegistryCache>) -> Self {
        Self {
            detector,
            registry,
            last_toast: Mutex::new(HashMap::new()),
        }
    }

    /// Returns `true` and updates `last_toast` if the drive's cooldown has expired
    /// (or the drive has never fired a toast). Returns `false` during the 30-second
    /// cooldown window. The block decision is NOT affected by this return value.
    fn should_notify(&self, drive: char) -> bool {
        const COOLDOWN: Duration = Duration::from_secs(30);
        let mut map = self.last_toast.lock();
        let now = Instant::now();
        // `is_none_or` treats a missing entry as "expired" so the first call always
        // returns true. `duration_since` is safe here because `now` is always >= stored
        // `last`; both are monotonic `Instant` values from the same clock.
        let expired = map
            .get(&drive)
            .is_none_or(|last| now.duration_since(*last) >= COOLDOWN);
        if expired {
            map.insert(drive, now);
        }
        expired
    }

    /// Resolves the trust tier for a given device identity by querying the
    /// registry cache. Returns `UsbTrustTier::Blocked` when the device is not
    /// registered (default-deny).
    ///
    /// # Arguments
    ///
    /// * `identity` - The [`DeviceIdentity`] to look up.
    /// * `sid` - Optional Windows user SID for per-user registry lookup.
    fn resolve_tier_for_identity(
        &self,
        identity: &DeviceIdentity,
        sid: Option<&str>,
    ) -> crate::device_registry::TrustTierResult {
        self.registry
            .trust_tier_for_with_sid(&identity.vid, &identity.pid, &identity.serial, sid)
    }

    /// Evaluates whether the given file operation should be blocked based on the
    /// USB trust tier of the drive the file resides on.
    ///
    /// Returns `Some(UsbBlockResult)` only for unregistered devices (default-deny
    /// fallback). All registered devices return `None` because active enforcement
    /// is now handled at the PnP level by [`DeviceController`](crate::device_controller::DeviceController):
    /// - `Blocked` devices are disabled on arrival and generate no file events.
    /// - `ReadOnly` devices have their volume DACL modified on arrival; NTFS
    ///   enforces the restriction.
    /// - `FullAccess` devices fall through to ABAC evaluation.
    ///
    /// # Arguments
    ///
    /// * `path` - Full file path of the operation (e.g., `E:\secret.docx`).
    /// * `action` - The [`FileAction`] being evaluated.
    ///
    /// # Returns
    ///
    /// - `Some(UsbBlockResult)` — unregistered device; default-deny at I/O level.
    /// - `None` — not a USB path, or registered device; proceed to ABAC or OS-level enforcement.
    #[must_use]
    pub fn check(&self, path: &str, _action: &FileAction) -> Option<UsbBlockResult> {
        // D-09: Extract drive letter — first character, must be ASCII alphabetic.
        // UNC paths start with `\\` and have no drive letter; return None immediately.
        let drive = extract_drive_letter(path)?;

        // Look up the DeviceIdentity for this drive letter.
        // If the drive is not in the USB detector's map, it is not a USB drive.
        let identity = {
            let map = self.detector.device_identities.read();
            map.get(&drive).cloned()
        };
        let identity = match identity {
            Some(id) => id,
            None => {
                // Defence-in-depth: a drive letter may be known as USB (via
                // `scan_existing_drives` at startup or a missed identity-capture
                // race) without an associated VID/PID/serial. In that case, we
                // cannot consult the device registry — but treating the drive as
                // "not a USB" and falling through to ABAC would violate the
                // default-deny posture (Zero Trust, CLAUDE.md §3.1). If the drive
                // is in `blocked_drives`, treat it as a known-USB-without-identity
                // and DENY all operations with tier=Blocked.
                if self.detector.blocked_drives.read().contains(&drive) {
                    let notify = self.should_notify(drive);
                    tracing::info!(
                        drive = %drive,
                        action = ?std::mem::discriminant(_action),
                        tier = ?UsbTrustTier::Blocked,
                        decision = ?Decision::DENY,
                        rule = "default-deny: known USB without captured identity",
                        "USB enforcement decision"
                    );
                    return Some(UsbBlockResult {
                        decision: Decision::DENY,
                        identity: DeviceIdentity {
                            vid: "unknown".into(),
                            pid: "unknown".into(),
                            serial: "unknown".into(),
                            description: format!("USB drive {} (identity not captured)", drive),
                        },
                        tier: UsbTrustTier::Blocked,
                        notify,
                        owner_sid: None,
                        owner_user: None,
                    });
                }
                return None;
            }
        };

        // Check if the device is explicitly registered in the device registry.
        // Registered devices are handled at the PnP level by DeviceController
        // (disable for Blocked, DACL modification for ReadOnly). Unregistered
        // devices default to deny at the I/O level as defence-in-depth.
        let is_registered =
            self.registry
                .has_device(&identity.vid, &identity.pid, &identity.serial);

        // Resolve current user SID for per-user registry lookup (USB-06).
        let current_sid = crate::identity::get_current_process_sid();
        let tier_result = self.resolve_tier_for_identity(&identity, current_sid.as_deref());

        if is_registered {
            // Registered device: active enforcement is handled by DeviceController.
            // Blocked → disabled on arrival; ReadOnly → DACL modified on arrival;
            // FullAccess → no action. All cases return None.
            tracing::info!(
                vid = %identity.vid,
                pid = %identity.pid,
                serial = %identity.serial,
                drive = %drive,
                action = ?std::mem::discriminant(_action),
                tier = ?tier_result.tier,
                decision = ?Decision::ALLOW,
                rule = %format!("registered device: {:?}", tier_result.tier),
                "USB enforcement decision"
            );
            None
        } else {
            // Unregistered device: default deny at the I/O level (fail-safe).
            let notify = self.should_notify(drive);
            tracing::info!(
                vid = %identity.vid,
                pid = %identity.pid,
                serial = %identity.serial,
                drive = %drive,
                action = ?std::mem::discriminant(_action),
                tier = ?UsbTrustTier::Blocked,
                decision = ?Decision::DENY,
                rule = "default-deny: unregistered device",
                "USB enforcement decision"
            );
            Some(UsbBlockResult {
                decision: Decision::DENY,
                identity,
                tier: UsbTrustTier::Blocked,
                notify,
                owner_sid: tier_result.owner_sid.clone(),
                owner_user: tier_result.owner_user.clone(),
            })
        }
    }
}

/// Extracts the uppercase drive letter from a Windows file path.
///
/// Returns `Some('E')` for `E:\data\file.txt` and `None` for:
/// - UNC paths (`\\server\share\...`)
/// - Paths that do not start with an ASCII alphabetic character
/// - Empty paths
fn extract_drive_letter(path: &str) -> Option<char> {
    // UNC paths start with `\\` — they are never local USB drives.
    if path.starts_with("\\\\") {
        return None;
    }
    let first = path.chars().next()?;
    if first.is_ascii_alphabetic() {
        Some(first.to_ascii_uppercase())
    } else {
        None
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::{HashMap, HashSet};

    use dlp_common::DeviceIdentity;
    use parking_lot::RwLock;

    /// Builds a UsbDetector with specific drive-letter to DeviceIdentity mappings.
    fn make_detector(entries: Vec<(char, &str, &str, &str)>) -> Arc<UsbDetector> {
        let mut map = HashMap::new();
        let mut blocked = HashSet::new();
        for (drive, vid, pid, serial) in entries {
            map.insert(
                drive,
                DeviceIdentity {
                    vid: vid.to_string(),
                    pid: pid.to_string(),
                    serial: serial.to_string(),
                    description: "Test Device".to_string(),
                },
            );
            blocked.insert(drive);
        }
        Arc::new(UsbDetector {
            blocked_drives: RwLock::new(blocked),
            device_identities: RwLock::new(map),
            ..Default::default()
        })
    }

    /// Builds a DeviceRegistryCache pre-seeded with the given trust tier.
    fn make_registry(
        vid: &str,
        pid: &str,
        serial: &str,
        tier: UsbTrustTier,
    ) -> Arc<DeviceRegistryCache> {
        let cache = Arc::new(DeviceRegistryCache::new());
        cache.seed_for_test(vid, pid, serial, tier);
        cache
    }

    fn written_action() -> FileAction {
        FileAction::Written {
            path: "E:\\file.txt".to_string(),
            process_id: 1,
            related_process_id: 1,
            byte_count: 100,
        }
    }

    fn created_action() -> FileAction {
        FileAction::Created {
            path: "E:\\file.txt".to_string(),
            process_id: 1,
            related_process_id: 1,
        }
    }

    fn deleted_action() -> FileAction {
        FileAction::Deleted {
            path: "E:\\file.txt".to_string(),
            process_id: 1,
            related_process_id: 1,
        }
    }

    fn moved_action() -> FileAction {
        FileAction::Moved {
            old_path: "E:\\a.txt".to_string(),
            new_path: "E:\\b.txt".to_string(),
            process_id: 1,
            related_process_id: 1,
        }
    }

    fn read_action() -> FileAction {
        FileAction::Read {
            path: "E:\\file.txt".to_string(),
            process_id: 1,
            related_process_id: 1,
            byte_count: 0,
        }
    }

    #[test]
    fn test_blocked_device_returns_none() {
        // Phase 31: Blocked devices are disabled at the PnP level by DeviceController.
        // UsbEnforcer::check() returns None for all registered tiers.
        let detector = make_detector(vec![('E', "0951", "1666", "SN001")]);
        let registry = make_registry("0951", "1666", "SN001", UsbTrustTier::Blocked);
        let enforcer = UsbEnforcer::new(detector, registry);

        assert_eq!(enforcer.check("E:\\file.txt", &written_action()), None);
        assert_eq!(enforcer.check("E:\\file.txt", &read_action()), None);
        assert_eq!(enforcer.check("E:\\file.txt", &created_action()), None);
        assert_eq!(enforcer.check("E:\\file.txt", &deleted_action()), None);
        assert_eq!(enforcer.check("E:\\file.txt", &moved_action()), None);
    }

    #[test]
    fn test_readonly_device_returns_none() {
        // Phase 31: ReadOnly devices have volume DACL modified by DeviceController.
        // UsbEnforcer::check() returns None for all registered tiers.
        let detector = make_detector(vec![('E', "0951", "1666", "SN001")]);
        let registry = make_registry("0951", "1666", "SN001", UsbTrustTier::ReadOnly);
        let enforcer = UsbEnforcer::new(detector, registry);

        assert_eq!(enforcer.check("E:\\file.txt", &written_action()), None);
        assert_eq!(enforcer.check("E:\\file.txt", &read_action()), None);
        assert_eq!(enforcer.check("E:\\file.txt", &created_action()), None);
        assert_eq!(enforcer.check("E:\\file.txt", &deleted_action()), None);
        assert_eq!(enforcer.check("E:\\file.txt", &moved_action()), None);
    }

    #[test]
    fn test_full_access_device_returns_none() {
        let detector = make_detector(vec![('E', "0951", "1666", "SN001")]);
        let registry = make_registry("0951", "1666", "SN001", UsbTrustTier::FullAccess);
        let enforcer = UsbEnforcer::new(detector, registry);

        assert_eq!(enforcer.check("E:\\file.txt", &written_action()), None);
        assert_eq!(enforcer.check("E:\\file.txt", &read_action()), None);
    }

    #[test]
    fn test_unc_path_returns_none() {
        let detector = make_detector(vec![]);
        let registry = Arc::new(DeviceRegistryCache::new());
        let enforcer = UsbEnforcer::new(detector, registry);

        // UNC paths have no drive letter — USB enforcement skipped.
        assert_eq!(
            enforcer.check("\\\\server\\share\\file.txt", &written_action()),
            None
        );
    }

    #[test]
    fn test_non_usb_drive_returns_none() {
        // Drive C is not in the USB detector's device_identities map.
        let detector = make_detector(vec![('E', "0951", "1666", "SN001")]);
        let registry = make_registry("0951", "1666", "SN001", UsbTrustTier::Blocked);
        let enforcer = UsbEnforcer::new(detector, registry);

        // C drive is not a USB drive, returns None.
        assert_eq!(
            enforcer.check("C:\\Users\\data\\file.txt", &written_action()),
            None
        );
    }

    #[test]
    fn test_extract_drive_letter_valid() {
        assert_eq!(extract_drive_letter("E:\\file.txt"), Some('E'));
        // Lowercase drive letter is normalized to uppercase (T-26-12 mitigation).
        assert_eq!(extract_drive_letter("e:\\file.txt"), Some('E'));
        assert_eq!(extract_drive_letter("C:\\Windows"), Some('C'));
    }

    #[test]
    fn test_extract_drive_letter_unc_returns_none() {
        assert_eq!(extract_drive_letter("\\\\server\\share"), None);
    }

    #[test]
    fn test_extract_drive_letter_empty_returns_none() {
        assert_eq!(extract_drive_letter(""), None);
    }

    /// T-26-14: Unregistered device defaults to Blocked (fail-safe).
    ///
    /// The device triple is present in the USB detector's drive-letter map
    /// (the drive letter IS known), but the VID/PID/serial are NOT in the
    /// device registry cache. `trust_tier_for` returns `Blocked` as the
    /// default — all operations are denied (CLAUDE.md section 3.1, Zero Trust).
    #[test]
    fn test_unregistered_device_defaults_to_blocked() {
        // Detector knows about drive E (device identity present), but the
        // registry has never been seeded with this VID/PID/serial.
        let detector = make_detector(vec![('E', "DEAD", "BEEF", "UNREGISTERED")]);
        // Empty registry — no seed_for_test call.
        let registry = Arc::new(DeviceRegistryCache::new());
        let enforcer = UsbEnforcer::new(detector, registry);

        // Write must be denied.
        let result = enforcer.check("E:\\secret.docx", &written_action());
        assert!(result.is_some());
        assert_eq!(result.unwrap().decision, Decision::DENY);

        // Read must also be denied (default-deny for unknown devices).
        let result = enforcer.check("E:\\file.txt", &read_action()).unwrap();
        assert_eq!(result.decision, Decision::DENY);
        assert_eq!(result.tier, UsbTrustTier::Blocked);
    }

    /// D-09: path starting with a non-ASCII-alphabetic character returns None.
    ///
    /// Linux-style paths (e.g., `/usr/local/file.txt`) start with `/` which
    /// is not an ASCII alphabetic character. No drive letter can be extracted,
    /// so USB enforcement is skipped entirely.
    #[test]
    fn test_non_alpha_path_returns_none() {
        let detector = make_detector(vec![]);
        let registry = Arc::new(DeviceRegistryCache::new());
        let enforcer = UsbEnforcer::new(detector, registry);

        // Path starting with `/` (Linux-style) has no Windows drive letter.
        assert_eq!(
            enforcer.check("/usr/local/file.txt", &written_action()),
            None
        );
    }

    /// Defence-in-depth: a drive letter known to be USB (via `scan_existing_drives`)
    /// but missing from `device_identities` (VID/PID/serial never captured) must still
    /// be denied on all operations. Without this guard, the enforcer would return `None`
    /// and fall through to ABAC, which allows the operation — the Phase 28 UAT bug.
    ///
    /// Precondition: `blocked_drives` contains the letter; `device_identities` is empty.
    #[test]
    fn test_known_usb_without_identity_is_denied() {
        // Build a detector with E in blocked_drives but nothing in device_identities —
        // simulating a USB plugged in before the agent started (scan_existing_drives
        // captures the drive letter but not the VID/PID/serial).
        let mut blocked = HashSet::new();
        blocked.insert('E');
        let detector = Arc::new(UsbDetector {
            blocked_drives: RwLock::new(blocked),
            device_identities: RwLock::new(HashMap::new()),
            ..Default::default()
        });
        let registry = Arc::new(DeviceRegistryCache::new());
        let enforcer = UsbEnforcer::new(detector, registry);

        for action in [
            written_action(),
            read_action(),
            created_action(),
            deleted_action(),
            moved_action(),
        ] {
            let result = enforcer.check("E:\\file.txt", &action);
            let r = result.expect("known USB without identity must be denied, not allowed");
            assert_eq!(r.decision, Decision::DENY, "action {action:?} must DENY");
            assert_eq!(
                r.tier,
                UsbTrustTier::Blocked,
                "action {action:?} must report Blocked tier"
            );
        }
    }

    /// Blocked drive without identity: returns default-deny with Blocked tier.
    ///
    /// When a drive is in `blocked_drives` but has no `DeviceIdentity` entry,
    /// the enforcer still denies all operations with a default identity
    /// (empty strings) as a defence-in-depth fallback.
    #[test]
    fn test_blocked_drive_without_identity_returns_blocked() {
        let detector = Arc::new(UsbDetector {
            blocked_drives: RwLock::new(HashSet::from(['E'])),
            device_identities: RwLock::new(HashMap::new()),
            ..Default::default()
        });
        let registry = Arc::new(DeviceRegistryCache::new());
        let enforcer = UsbEnforcer::new(detector, registry);
        let result = enforcer.check("E:\\file.txt", &written_action());
        assert!(result.is_some());
        let r = result.unwrap();
        assert_eq!(r.decision, Decision::DENY);
        assert_eq!(r.tier, UsbTrustTier::Blocked);
        assert_eq!(r.identity.vid, "unknown");
        assert_eq!(r.identity.pid, "unknown");
        assert_eq!(r.identity.serial, "unknown");
        assert!(r.identity.description.contains("USB drive E"));
        assert!(r.notify); // first call
    }

    /// FullAccess device: all actions are allowed (fall through to ABAC).
    ///
    /// Verifies that Written, Read, and Created actions all return None
    /// when the device trust tier is FullAccess.
    #[test]
    fn test_full_access_device_all_actions_allowed() {
        let detector = make_detector(vec![('E', "0951", "1666", "SN001")]);
        let registry = make_registry("0951", "1666", "SN001", UsbTrustTier::FullAccess);
        let enforcer = UsbEnforcer::new(detector, registry);
        assert_eq!(enforcer.check("E:\\file.txt", &written_action()), None);
        assert_eq!(enforcer.check("E:\\file.txt", &read_action()), None);
        assert_eq!(enforcer.check("E:\\file.txt", &created_action()), None);
    }

    /// Per-drive isolation: different drives can have different trust tiers.
    ///
    /// Drive E is unregistered (default Blocked → I/O-level deny), drive F is FullAccess.
    /// Operations on each drive must be evaluated independently.
    #[test]
    fn test_per_drive_isolation() {
        let mut map = HashMap::new();
        let mut blocked = HashSet::new();
        map.insert(
            'E',
            DeviceIdentity {
                vid: "0951".into(),
                pid: "1666".into(),
                serial: "SN001".into(),
                description: "Test".into(),
            },
        );
        map.insert(
            'F',
            DeviceIdentity {
                vid: "0951".into(),
                pid: "1667".into(),
                serial: "SN002".into(),
                description: "Test2".into(),
            },
        );
        blocked.insert('E');
        blocked.insert('F');
        let detector = Arc::new(UsbDetector {
            blocked_drives: RwLock::new(blocked),
            device_identities: RwLock::new(map),
            ..Default::default()
        });
        let registry = Arc::new(DeviceRegistryCache::new());
        // E is NOT seeded → default-deny at I/O level (unregistered device fallback).
        registry.seed_for_test("0951", "1667", "SN002", UsbTrustTier::FullAccess);
        let enforcer = UsbEnforcer::new(detector, registry);
        // E is unregistered → default deny (defence-in-depth).
        assert!(enforcer.check("E:\\file.txt", &written_action()).is_some());
        // F is FullAccess → fall through to ABAC.
        assert_eq!(enforcer.check("F:\\file.txt", &written_action()), None);
    }

    // -------------------------------------------------------------------------
    // OP-02: USB Enforcement Structured Logging (Phase 38.6)
    // -------------------------------------------------------------------------

    /// resolve_tier_for_identity returns the correct tier for registered devices.
    #[test]
    fn test_resolve_tier_for_identity_registered() {
        let detector = make_detector(vec![('E', "0951", "1666", "SN001")]);
        let registry = make_registry("0951", "1666", "SN001", UsbTrustTier::ReadOnly);
        let enforcer = UsbEnforcer::new(detector, registry);

        let identity = DeviceIdentity {
            vid: "0951".into(),
            pid: "1666".into(),
            serial: "SN001".into(),
            description: "Test".into(),
        };
        assert_eq!(
            enforcer.resolve_tier_for_identity(&identity, None).tier,
            UsbTrustTier::ReadOnly
        );
    }

    /// resolve_tier_for_identity returns Blocked for unregistered devices.
    #[test]
    fn test_resolve_tier_for_identity_unregistered_defaults_blocked() {
        let detector = make_detector(vec![('E', "0951", "1666", "SN001")]);
        let registry = Arc::new(DeviceRegistryCache::new());
        // No seed — device is unregistered.
        let enforcer = UsbEnforcer::new(detector, registry);

        let identity = DeviceIdentity {
            vid: "0951".into(),
            pid: "1666".into(),
            serial: "SN001".into(),
            description: "Test".into(),
        };
        assert_eq!(
            enforcer.resolve_tier_for_identity(&identity, None).tier,
            UsbTrustTier::Blocked
        );
    }

    /// Unregistered device block includes correct decision fields.
    ///
    /// Verifies that the UsbBlockResult for an unregistered device has the
    /// expected fields populated so that tracing spans can reference them.
    #[test]
    fn test_unregistered_block_result_fields() {
        let detector = make_detector(vec![('E', "DEAD", "BEEF", "UNREG")]);
        let registry = Arc::new(DeviceRegistryCache::new());
        let enforcer = UsbEnforcer::new(detector, registry);

        let result = enforcer.check("E:\\file.txt", &written_action());
        assert!(result.is_some());
        let r = result.unwrap();
        assert_eq!(r.decision, Decision::DENY);
        assert_eq!(r.tier, UsbTrustTier::Blocked);
        assert_eq!(r.identity.vid, "DEAD");
        assert_eq!(r.identity.pid, "BEEF");
        assert_eq!(r.identity.serial, "UNREG");
    }

    /// Known-USB-without-identity block result has unknown fields.
    ///
    /// When a drive is in blocked_drives but has no DeviceIdentity, the
    /// block result uses "unknown" for vid/pid/serial so tracing spans still
    /// have structured data.
    #[test]
    fn test_known_usb_without_identity_block_result_fields() {
        let detector = Arc::new(UsbDetector {
            blocked_drives: RwLock::new(HashSet::from(['E'])),
            device_identities: RwLock::new(HashMap::new()),
            ..Default::default()
        });
        let registry = Arc::new(DeviceRegistryCache::new());
        let enforcer = UsbEnforcer::new(detector, registry);

        let result = enforcer.check("E:\\file.txt", &written_action());
        assert!(result.is_some());
        let r = result.unwrap();
        assert_eq!(r.identity.vid, "unknown");
        assert_eq!(r.identity.pid, "unknown");
        assert_eq!(r.identity.serial, "unknown");
        assert!(r.identity.description.contains("USB drive E"));
    }

    /// FullAccess registered device returns None (allow path).
    ///
    /// Verifies that the allow path returns None and that resolve_tier_for_identity
    /// correctly identifies the FullAccess tier.
    #[test]
    fn test_fullaccess_registered_returns_none_with_tier() {
        let detector = make_detector(vec![('E', "0951", "1666", "SN001")]);
        let registry = make_registry("0951", "1666", "SN001", UsbTrustTier::FullAccess);
        let enforcer = UsbEnforcer::new(detector, registry);

        // resolve_tier_for_identity must report FullAccess.
        let identity = DeviceIdentity {
            vid: "0951".into(),
            pid: "1666".into(),
            serial: "SN001".into(),
            description: "Test".into(),
        };
        assert_eq!(
            enforcer.resolve_tier_for_identity(&identity, None).tier,
            UsbTrustTier::FullAccess
        );

        // check() returns None for registered devices.
        assert_eq!(enforcer.check("E:\\file.txt", &written_action()), None);
    }
}

//! Fixed-disk enforcement layer (DISK-04, Phase 36).
//!
//! [`DiskEnforcer`] bridges the Phase 33-35 [`DiskEnumerator`] (frozen
//! `instance_id_map` allowlist + live `drive_letter_map`) and the
//! [`run_event_loop`](crate::interception::run_event_loop) write-path
//! to enforce the disk allowlist at file I/O time.
//!
//! ## Decision logic (per 36-CONTEXT.md D-06, D-07)
//!
//! 1. Action filter: only `Created`, `Written`, `Moved` are intercepted (DISK-04).
//!    `Read` and `Deleted` always return `None`.
//! 2. Fail-closed: if [`get_disk_enumerator`] returns `None` or
//!    [`DiskEnumerator::is_ready`] is false, ALL fixed-disk writes are blocked
//!    with a placeholder identity (D-06).
//! 3. Drive-letter resolution: extract the first ASCII alpha character of the
//!    path; reject UNC paths and non-alpha leading characters.
//! 4. Live-disk lookup: `disk_for_drive_letter(letter)` returns `None` when the
//!    drive is not a tracked fixed disk -> pass through to ABAC.
//! 5. Allowlist check: `disk_for_instance_id(live.instance_id)` -> if `None`,
//!    block with the live identity.
//! 6. Compound serial check (D-11 physical-swap closure): when both registered
//!    and live serials are `Some(...)` and differ, block with the live identity.
//! 7. Otherwise, return `None` (fall through to ABAC).
//!
//! ## Cooldown semantics (D-02)
//!
//! `last_toast: parking_lot::Mutex<HashMap<char, Instant>>` enforces a
//! 30-second per-drive-letter toast cooldown. The block decision is ALWAYS
//! applied; only the toast/notify side-effect is suppressed during cooldown.

use std::collections::HashMap;
use std::time::{Duration, Instant};

use dlp_common::{Decision, DiskIdentity};
use parking_lot::Mutex;

use crate::detection::disk::get_disk_enumerator;
use crate::interception::FileAction;

/// Result returned by [`DiskEnforcer::check`] when a fixed-disk write is blocked.
///
/// Carries the [`Decision`], the live [`DiskIdentity`] that triggered the block,
/// and a `notify` flag indicating whether the per-drive 30-second toast cooldown
/// has elapsed. The block decision is always applied regardless of `notify`.
#[derive(Debug, Clone, PartialEq)]
pub struct DiskBlockResult {
    /// The enforcement decision -- currently always [`Decision::DENY`].
    pub decision: Decision,
    /// The live [`DiskIdentity`] from `drive_letter_map` at enforcement time.
    /// For the fail-closed startup-window case (D-06), only `drive_letter` is
    /// populated and other fields use `Default` values.
    pub disk: DiskIdentity,
    /// `true` if the UI should display a toast; `false` when the 30-second
    /// per-drive cooldown is active.
    pub notify: bool,
}

/// Enforces the disk allowlist at file I/O time (DISK-04, Phase 36).
///
/// Wraps the global [`DiskEnumerator`] (Phase 33-35) internally via
/// [`get_disk_enumerator`] -- the enumerator must be installed via
/// `set_disk_enumerator` before [`DiskEnforcer::check`] is called.
/// Held behind `Arc` so it can be shared between the event loop and other
/// subsystems without cloning the cooldown map.
pub struct DiskEnforcer {
    /// Per-drive-letter timestamp of the last toast broadcast.
    /// Enforces the 30-second cooldown per CONTEXT.md D-02.
    last_toast: Mutex<HashMap<char, Instant>>,
}

impl DiskEnforcer {
    /// Constructs a new [`DiskEnforcer`] with an empty cooldown map.
    ///
    /// The enforcer wraps [`get_disk_enumerator`] internally; the global
    /// `DiskEnumerator` must be installed via `set_disk_enumerator`
    /// (typically in `service.rs` startup) before [`Self::check`] is called.
    #[must_use]
    pub fn new() -> Self {
        Self {
            last_toast: Mutex::new(HashMap::new()),
        }
    }

    /// Returns `true` and updates `last_toast` if the drive's cooldown has
    /// expired (or the drive has never fired a toast). Returns `false` during
    /// the 30-second cooldown window. The block decision is NOT affected by
    /// this return value (D-02).
    fn should_notify(&self, drive: char) -> bool {
        const COOLDOWN: Duration = Duration::from_secs(30);
        let mut map = self.last_toast.lock();
        let now = Instant::now();
        // `is_none_or` treats a missing entry as "expired" so the first call
        // always returns true. `duration_since` is safe because both Instants
        // are monotonic from the same clock.
        let expired = map
            .get(&drive)
            .is_none_or(|last| now.duration_since(*last) >= COOLDOWN);
        if expired {
            map.insert(drive, now);
        }
        expired
    }

    /// Evaluates whether the given file operation should be blocked based on
    /// the disk allowlist (per CONTEXT.md D-04 through D-07).
    ///
    /// Returns `Some(DiskBlockResult)` when the operation must be blocked;
    /// returns `None` when the operation is allowed to fall through to ABAC.
    ///
    /// # Arguments
    ///
    /// * `path` - Full file path of the operation (e.g., `E:\\file.txt`).
    /// * `action` - The [`FileAction`] being evaluated.
    ///
    /// # Returns
    ///
    /// - `None` for `FileAction::Read` or `FileAction::Deleted` (DISK-04 scope).
    /// - `None` for paths whose drive letter is not a tracked fixed disk.
    /// - `None` for allowlisted disks with matching serials.
    /// - `Some(DiskBlockResult)` when the disk is unregistered, the serial mismatches,
    ///   or the enumerator is not yet ready (D-06 fail-closed).
    #[must_use]
    pub fn check(&self, path: &str, action: &FileAction) -> Option<DiskBlockResult> {
        // DISK-04 action filter: only intercept write-path actions.
        // FileAction::Read (DLP design: read is allowed) and FileAction::Deleted
        // (metadata operation, not a write per CONTEXT.md D-04) both pass through.
        if !matches!(
            action,
            FileAction::Created { .. } | FileAction::Written { .. } | FileAction::Moved { .. }
        ) {
            return None;
        }

        // D-06 fail-closed: if the enumerator has not yet been installed in the
        // global OnceLock, the agent is in its startup window. Block ALL fixed-
        // disk writes with a placeholder identity carrying only the drive letter.
        //
        // Pitfall 3 (RESEARCH.md): the `?` operator on `get_disk_enumerator()`
        // would mean "no disk context = pass through" -- WRONG. Handle the None
        // case explicitly as fail-closed.
        let enumerator = match get_disk_enumerator() {
            Some(e) => e,
            None => {
                // WR-06: when the drive letter cannot be resolved (UNC, empty,
                // or malformed path), do not insert the '?' sentinel into the
                // per-drive cooldown map.  All unresolvable paths share the
                // same sentinel which would suppress toast notifications for
                // distinct paths after the first 30-second window.  Use
                // notify:false instead — the user cannot act on a path-less
                // notification anyway.
                let letter_opt = drive_letter_from_path(path);
                return Some(DiskBlockResult {
                    decision: Decision::DENY,
                    disk: DiskIdentity {
                        drive_letter: letter_opt,
                        ..Default::default()
                    },
                    notify: letter_opt.is_some_and(|l| self.should_notify(l)),
                });
            }
        };

        // D-06 fail-closed: enumeration not yet complete -- block all writes.
        if !enumerator.is_ready() {
            let letter_opt = drive_letter_from_path(path);
            return Some(DiskBlockResult {
                decision: Decision::DENY,
                disk: DiskIdentity {
                    drive_letter: letter_opt,
                    ..Default::default()
                },
                notify: letter_opt.is_some_and(|l| self.should_notify(l)),
            });
        }

        // D-09: extract drive letter; UNC and non-alpha leading characters mean
        // we cannot identify a fixed disk -- pass through.
        let letter = drive_letter_from_path(path)?;

        // D-07 step 2: if the drive letter is not in drive_letter_map, the path
        // is not on a tracked fixed disk -- pass through to ABAC.
        let live_disk = enumerator.disk_for_drive_letter(letter)?;

        // D-07 step 3: check the frozen allowlist (instance_id_map).
        let registered = enumerator.disk_for_instance_id(&live_disk.instance_id);

        // D-07 step 4 / D-11: compound serial check closes the physical-swap
        // bypass. Both stored and live serials must be `Some(...)` for a
        // mismatch to fire; if either is `None`, defer to allowlist presence.
        let serial_mismatch = registered
            .as_ref()
            .and_then(|r| r.serial.as_ref())
            .zip(live_disk.serial.as_ref())
            .map(|(stored, live)| stored != live)
            .unwrap_or(false);

        // Phase 45 (DISK-07): grace period check for unregistered disks.
        // If the disk is in grace period, allow reads but block writes.
        // If grace period expired (or never started), use normal block behavior.
        if registered.is_none() || serial_mismatch {
            // Check if this disk is in an active grace period.
            if enumerator.is_in_grace_period(&live_disk.instance_id) {
                // Grace period active: block writes, allow reads.
                // FileAction filter at top of check() already ensures we only
                // intercept write-path actions, so reads are implicitly allowed.
                let notify = self.should_notify(letter);
                return Some(DiskBlockResult {
                    decision: Decision::DENY,
                    disk: live_disk,
                    notify,
                });
            }

            // No grace period (or expired): normal full block.
            let notify = self.should_notify(letter);
            return Some(DiskBlockResult {
                decision: Decision::DENY,
                disk: live_disk,
                notify,
            });
        }

        // D-07 step 5: allowlisted with matching (or both-None) serial -- ABAC.
        None
    }
}

impl Default for DiskEnforcer {
    fn default() -> Self {
        Self::new()
    }
}

/// Extracts the uppercase drive letter from a Windows file path.
///
/// Returns `Some('E')` for `E:\\data\\file.txt` and `None` for:
/// - UNC paths (`\\\\server\\share\\...`)
/// - Paths that do not start with an ASCII alphabetic character
/// - Empty paths
///
/// Identical contract to `extract_drive_letter` in `usb_enforcer.rs`; kept
/// as a private free function so the disk enforcer remains independent of
/// USB code (the two modules are sibling enforcers, not a shared abstraction).
fn drive_letter_from_path(path: &str) -> Option<char> {
    // UNC paths start with `\\` -- never local fixed drives.
    if path.starts_with("\\\\") {
        return None;
    }
    let first = path.chars().next()?;
    if first.is_ascii_alphabetic() {
        Some(first.to_ascii_uppercase())
    } else {
        None
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Arc;
    use std::sync::OnceLock;

    use dlp_common::{BusType, DiskIdentity};

    use crate::detection::disk::{get_disk_enumerator, set_disk_enumerator, DiskEnumerator};
    // Shared process-wide lock that serializes all tests touching the global
    // DiskEnumerator OnceLock (disk_enforcer::tests + detection::disk::tests).
    use crate::test_helpers::DISK_TEST_LOCK;

    /// Returns the global DiskEnumerator, installing one if absent.
    ///
    /// We never construct a fresh enumerator per test (OnceLock allows only
    /// one set call). Instead we reuse the singleton and reset its fields.
    fn ensure_enumerator() -> Arc<DiskEnumerator> {
        static FALLBACK: OnceLock<Arc<DiskEnumerator>> = OnceLock::new();
        if let Some(e) = get_disk_enumerator() {
            return e;
        }
        let fresh = FALLBACK
            .get_or_init(|| Arc::new(DiskEnumerator::new()))
            .clone();
        set_disk_enumerator(Arc::clone(&fresh));
        fresh
    }

    /// Resets the enumerator's locked state to "not ready, empty maps".
    /// Caller must hold TEST_LOCK.
    fn reset_enumerator(enumerator: &DiskEnumerator) {
        enumerator.discovered_disks.write().clear();
        enumerator.drive_letter_map.write().clear();
        enumerator.instance_id_map.write().clear();
        *enumerator.enumeration_complete.write() = false;
    }

    /// Marks the enumerator as ready and seeds `drive_letter_map` /
    /// `instance_id_map` with the provided pairs. Caller holds TEST_LOCK.
    fn seed_enumerator(
        enumerator: &DiskEnumerator,
        drive_letter_pairs: &[(char, DiskIdentity)],
        instance_id_pairs: &[(String, DiskIdentity)],
    ) {
        {
            let mut dlm = enumerator.drive_letter_map.write();
            for (letter, disk) in drive_letter_pairs {
                dlm.insert(*letter, disk.clone());
            }
        }
        {
            let mut iim = enumerator.instance_id_map.write();
            for (id, disk) in instance_id_pairs {
                iim.insert(id.clone(), disk.clone());
            }
        }
        *enumerator.enumeration_complete.write() = true;
    }

    /// Builds a DiskIdentity test fixture with all fields specified.
    fn make_disk(
        instance_id: &str,
        drive_letter: Option<char>,
        serial: Option<&str>,
    ) -> DiskIdentity {
        DiskIdentity {
            instance_id: instance_id.to_string(),
            bus_type: BusType::Sata,
            model: format!("Model-{instance_id}"),
            drive_letter,
            serial: serial.map(|s| s.to_string()),
            size_bytes: Some(500_000_000_000),
            is_boot_disk: false,
            encryption_status: None,
            encryption_method: None,
            encryption_checked_at: None,
        }
    }

    fn write_action(path: &str) -> FileAction {
        FileAction::Written {
            path: path.to_string(),
            process_id: 100,
            related_process_id: 100,
            byte_count: 100,
        }
    }

    fn create_action(path: &str) -> FileAction {
        FileAction::Created {
            path: path.to_string(),
            process_id: 100,
            related_process_id: 100,
        }
    }

    fn move_action(old_path: &str, new_path: &str) -> FileAction {
        FileAction::Moved {
            old_path: old_path.to_string(),
            new_path: new_path.to_string(),
            process_id: 100,
            related_process_id: 100,
        }
    }

    fn read_action(path: &str) -> FileAction {
        FileAction::Read {
            path: path.to_string(),
            process_id: 100,
            related_process_id: 100,
            byte_count: 100,
        }
    }

    fn delete_action(path: &str) -> FileAction {
        FileAction::Deleted {
            path: path.to_string(),
            process_id: 100,
            related_process_id: 100,
        }
    }

    // ---------- DISK-04: Read action passes through ----------
    #[test]
    fn test_read_action_returns_none() {
        let _guard = DISK_TEST_LOCK.lock();
        let enumerator = ensure_enumerator();
        reset_enumerator(&enumerator);
        // Even with an unregistered disk on E:, Read must pass through.
        let live = make_disk("ID-UNREGISTERED", Some('E'), Some("SN-LIVE"));
        seed_enumerator(&enumerator, &[('E', live)], &[]);

        let enforcer = DiskEnforcer::new();
        assert_eq!(
            enforcer.check(r"E:\file.txt", &read_action(r"E:\file.txt")),
            None
        );
    }

    // ---------- DISK-04: Deleted action passes through ----------
    #[test]
    fn test_deleted_action_returns_none() {
        let _guard = DISK_TEST_LOCK.lock();
        let enumerator = ensure_enumerator();
        reset_enumerator(&enumerator);
        let live = make_disk("ID-UNREGISTERED", Some('E'), Some("SN-LIVE"));
        seed_enumerator(&enumerator, &[('E', live)], &[]);

        let enforcer = DiskEnforcer::new();
        assert_eq!(
            enforcer.check(r"E:\file.txt", &delete_action(r"E:\file.txt")),
            None
        );
    }

    // ---------- D-06: enumerator absent -> fail-closed ----------
    // NOTE: cannot test the "OnceLock empty" case directly because the
    // global may already be installed by a prior test in the same binary.
    // We simulate the equivalent state by setting enumeration_complete = false.
    // The "enumerator absent" branch is structurally identical (same error
    // result construction); both arms are exercised by code review of the
    // `match get_disk_enumerator()` block. The not-ready branch is the
    // operationally relevant case at runtime: enumerator installed but
    // not yet ready in the 4-second startup window per Phase 33 D-04.
    #[test]
    fn test_write_blocked_when_not_ready_fail_closed() {
        let _guard = DISK_TEST_LOCK.lock();
        let enumerator = ensure_enumerator();
        reset_enumerator(&enumerator); // enumeration_complete = false

        let enforcer = DiskEnforcer::new();
        let result = enforcer
            .check(r"E:\secret.docx", &write_action(r"E:\secret.docx"))
            .expect("fail-closed: write must block when not ready");
        assert_eq!(result.decision, Decision::DENY);
        assert_eq!(result.disk.drive_letter, Some('E'));
        // Placeholder identity has empty instance_id and model.
        assert!(result.disk.instance_id.is_empty());
        assert!(result.notify, "first call -> notify must be true");
    }

    // ---------- D-07 step 2: not-tracked drive letter -> pass through ----------
    #[test]
    fn test_path_not_in_drive_letter_map_passes() {
        let _guard = DISK_TEST_LOCK.lock();
        let enumerator = ensure_enumerator();
        reset_enumerator(&enumerator);
        // Seed E only; enforcer is asked about Z.
        let e_disk = make_disk("ID-E", Some('E'), Some("SN-E"));
        seed_enumerator(
            &enumerator,
            &[('E', e_disk.clone())],
            &[("ID-E".into(), e_disk)],
        );

        let enforcer = DiskEnforcer::new();
        assert_eq!(
            enforcer.check(r"Z:\file.txt", &write_action(r"Z:\file.txt")),
            None
        );
    }

    // ---------- D-07 step 3: unregistered disk -> block ----------
    #[test]
    fn test_unregistered_disk_blocked_on_create_write_move() {
        let _guard = DISK_TEST_LOCK.lock();
        let enumerator = ensure_enumerator();
        reset_enumerator(&enumerator);
        // E is in drive_letter_map but instance_id_map is empty -- unregistered.
        let live = make_disk("ID-LIVE", Some('E'), Some("SN-LIVE"));
        seed_enumerator(&enumerator, &[('E', live.clone())], &[]);

        let enforcer = DiskEnforcer::new();

        for action in [
            create_action(r"E:\new.txt"),
            write_action(r"E:\file.txt"),
            move_action(r"E:\a.txt", r"E:\b.txt"),
        ] {
            let result = enforcer
                .check(r"E:\file.txt", &action)
                .unwrap_or_else(|| panic!("unregistered disk must block {action:?}"));
            assert_eq!(result.decision, Decision::DENY);
            assert_eq!(result.disk.instance_id, "ID-LIVE");
            assert_eq!(result.disk.drive_letter, Some('E'));
        }
    }

    // ---------- D-07 step 4: serial mismatch (physical-swap) -> block ----------
    #[test]
    fn test_serial_mismatch_blocked() {
        let _guard = DISK_TEST_LOCK.lock();
        let enumerator = ensure_enumerator();
        reset_enumerator(&enumerator);
        // Same instance_id but different serial -- physical swap.
        let registered = make_disk("ID-SHARED", Some('E'), Some("SN-REGISTERED"));
        let live = make_disk("ID-SHARED", Some('E'), Some("SN-DIFFERENT"));
        seed_enumerator(
            &enumerator,
            &[('E', live.clone())],
            &[("ID-SHARED".into(), registered)],
        );

        let enforcer = DiskEnforcer::new();
        let result = enforcer
            .check(r"E:\file.txt", &write_action(r"E:\file.txt"))
            .expect("serial mismatch must block");
        assert_eq!(result.decision, Decision::DENY);
        // Live disk identity is the one carried in the result (D-16).
        assert_eq!(result.disk.serial, Some("SN-DIFFERENT".to_string()));
    }

    // ---------- D-07 step 5: allowlisted, serials match -> pass through ----------
    #[test]
    fn test_allowlisted_disk_passes() {
        let _guard = DISK_TEST_LOCK.lock();
        let enumerator = ensure_enumerator();
        reset_enumerator(&enumerator);
        let registered = make_disk("ID-MATCH", Some('E'), Some("SN-MATCH"));
        let live = registered.clone();
        seed_enumerator(
            &enumerator,
            &[('E', live)],
            &[("ID-MATCH".into(), registered)],
        );

        let enforcer = DiskEnforcer::new();
        assert_eq!(
            enforcer.check(r"E:\file.txt", &write_action(r"E:\file.txt")),
            None
        );
        // Both serials None also passes (no mismatch when either side missing).
        reset_enumerator(&enumerator);
        let registered_no_serial = make_disk("ID-NS", Some('E'), None);
        let live_no_serial = make_disk("ID-NS", Some('E'), None);
        seed_enumerator(
            &enumerator,
            &[('E', live_no_serial)],
            &[("ID-NS".into(), registered_no_serial)],
        );
        assert_eq!(
            enforcer.check(r"E:\file.txt", &write_action(r"E:\file.txt")),
            None
        );
    }

    // ---------- D-02: 30-second cooldown per drive letter ----------
    #[test]
    fn test_should_notify_cooldown() {
        let _guard = DISK_TEST_LOCK.lock();
        let enumerator = ensure_enumerator();
        reset_enumerator(&enumerator);
        // Force a block path so should_notify is exercised by check.
        let live = make_disk("ID-CD", Some('F'), Some("SN-CD"));
        seed_enumerator(&enumerator, &[('F', live)], &[]);

        let enforcer = DiskEnforcer::new();
        let first = enforcer
            .check(r"F:\1.txt", &write_action(r"F:\1.txt"))
            .expect("first block fires");
        assert!(first.notify, "first block on drive must notify");

        let second = enforcer
            .check(r"F:\2.txt", &write_action(r"F:\2.txt"))
            .expect("second block also fires");
        assert!(!second.notify, "second block within 30s must NOT notify");

        // Different drive letter has its own cooldown -- still notifies.
        reset_enumerator(&enumerator);
        let live_g = make_disk("ID-G", Some('G'), None);
        seed_enumerator(&enumerator, &[('G', live_g)], &[]);
        let g_first = enforcer
            .check(r"G:\1.txt", &write_action(r"G:\1.txt"))
            .expect("first block on G fires");
        assert!(g_first.notify, "different drive letter must notify");
    }

    // ---------- UNC path passes through ----------
    #[test]
    fn test_unc_path_returns_none() {
        let _guard = DISK_TEST_LOCK.lock();
        let enumerator = ensure_enumerator();
        reset_enumerator(&enumerator);
        *enumerator.enumeration_complete.write() = true; // ready, but UNC has no letter

        let enforcer = DiskEnforcer::new();
        assert_eq!(
            enforcer.check(
                r"\\server\share\file.txt",
                &write_action(r"\\server\share\file.txt")
            ),
            None
        );
    }

    // ---------- Helper sanity: drive_letter_from_path ----------
    #[test]
    fn test_drive_letter_helpers() {
        assert_eq!(drive_letter_from_path(r"E:\file.txt"), Some('E'));
        assert_eq!(drive_letter_from_path(r"e:\file.txt"), Some('E'));
        assert_eq!(drive_letter_from_path(r"\\server\share"), None);
        assert_eq!(drive_letter_from_path("/usr/local"), None);
        assert_eq!(drive_letter_from_path(""), None);
    }

    // ---------- Phase 45: Grace period / quarantine (DISK-07) ----------

    /// DiskEnforcer::check blocks writes for a disk in grace period.
    #[test]
    fn test_disk_enforcer_blocks_writes_during_grace_period() {
        let _guard = DISK_TEST_LOCK.lock();
        let enumerator = ensure_enumerator();
        reset_enumerator(&enumerator);

        // Unregistered disk in drive_letter_map with grace period active.
        let live = make_disk("ID-GRACE", Some('E'), Some("SN-GRACE"));
        seed_enumerator(&enumerator, &[('E', live.clone())], &[]);
        enumerator.set_grace_period_seconds(300);
        enumerator
            .grace_period_map
            .write()
            .insert("ID-GRACE".to_string(), Instant::now());

        let enforcer = DiskEnforcer::new();

        // Write action must be blocked (DENY) even though disk is in drive_letter_map.
        let result = enforcer
            .check(r"E:\file.txt", &write_action(r"E:\file.txt"))
            .expect("write must be blocked during grace period");
        assert_eq!(result.decision, Decision::DENY);
        assert_eq!(result.disk.instance_id, "ID-GRACE");
    }

    /// DiskEnforcer::check allows reads for a disk in grace period.
    #[test]
    fn test_disk_enforcer_allows_reads_during_grace_period() {
        let _guard = DISK_TEST_LOCK.lock();
        let enumerator = ensure_enumerator();
        reset_enumerator(&enumerator);

        let live = make_disk("ID-GRACE-READ", Some('F'), Some("SN-GRACE-READ"));
        seed_enumerator(&enumerator, &[('F', live.clone())], &[]);
        enumerator.set_grace_period_seconds(300);
        enumerator
            .grace_period_map
            .write()
            .insert("ID-GRACE-READ".to_string(), Instant::now());

        let enforcer = DiskEnforcer::new();

        // Read action must pass through (None) even for unregistered disk in grace.
        assert_eq!(
            enforcer.check(r"F:\file.txt", &read_action(r"F:\file.txt")),
            None,
            "read must be allowed during grace period"
        );
    }

    /// DiskEnforcer::check uses normal block behavior when grace period expired.
    #[test]
    fn test_disk_enforcer_blocks_when_grace_period_expired() {
        let _guard = DISK_TEST_LOCK.lock();
        let enumerator = ensure_enumerator();
        reset_enumerator(&enumerator);

        let live = make_disk("ID-GRACE-EXP", Some('G'), Some("SN-GRACE-EXP"));
        seed_enumerator(&enumerator, &[('G', live.clone())], &[]);
        // Very short grace period that has already expired.
        enumerator.set_grace_period_seconds(1);
        enumerator.grace_period_map.write().insert(
            "ID-GRACE-EXP".to_string(),
            Instant::now() - Duration::from_secs(10),
        );

        let enforcer = DiskEnforcer::new();

        // Write action still blocks (grace period expired = normal unregistered behavior).
        let result = enforcer
            .check(r"G:\file.txt", &write_action(r"G:\file.txt"))
            .expect("write must be blocked when grace period expired");
        assert_eq!(result.decision, Decision::DENY);
        assert_eq!(result.disk.instance_id, "ID-GRACE-EXP");
    }
}

//! ABAC types — Subject, Resource, Environment, Action, and Policy.
//!
//! These types define the attribute model used by the Policy Engine's
//! Attribute-Based Access Control evaluation layer.

use crate::endpoint::AppIdentity;
use serde::{Deserialize, Serialize};

/// The action the user is attempting to perform on a resource.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[allow(non_camel_case_types)]
pub enum Action {
    /// Read a file.
    #[default]
    READ,
    /// Write or modify a file.
    WRITE,
    /// Copy a file (e.g., to USB or network share).
    COPY,
    /// Delete a file.
    DELETE,
    /// Move a file (rename or relocate).
    MOVE,
    /// Paste from clipboard (copying text/data into an application).
    PASTE,
    /// Admin created a new policy via the admin API.
    PolicyCreate,
    /// Admin updated an existing policy via the admin API.
    PolicyUpdate,
    /// Admin deleted a policy via the admin API.
    PolicyDelete,
    /// Admin changed own password via the admin API.
    PasswordChange,
    /// Admin added a disk to the server-side disk allowlist (Phase 37, AUDIT-03).
    DiskRegistryAdd,
    /// Admin removed a disk from the server-side disk allowlist (Phase 37, AUDIT-03).
    DiskRegistryRemove,
    /// Drag-and-drop operation (Phase 40, APP-08).
    DRAG_DROP,
}

/// The access context describes how the file operation originated.
///
/// `local` — the file operation originates from a process running locally.
/// `smb` — the file operation originates from a remote client over SMB.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "lowercase")]
pub enum AccessContext {
    /// Operation originates from the local process.
    #[default]
    Local,
    /// Operation originates from a remote SMB client.
    Smb,
}

/// The system action the ABAC engine returns after evaluation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
pub enum Decision {
    /// Permit the operation without additional logging.
    #[default]
    ALLOW,
    /// Block the operation and log the event.
    DENY,
    /// Permit the operation but emit an audit event.
    #[serde(rename = "ALLOW_WITH_LOG")]
    AllowWithLog,
    /// Block the operation, log the event, and trigger an immediate SIEM/admin alert.
    #[serde(rename = "DENY_WITH_ALERT")]
    DenyWithAlert,
}

impl Decision {
    /// Returns `true` if this decision blocks the operation.
    #[must_use]
    pub fn is_denied(self) -> bool {
        matches!(self, Self::DENY | Self::DenyWithAlert)
    }

    /// Returns `true` if this decision should trigger an alert.
    #[must_use]
    pub fn is_alert(self) -> bool {
        matches!(self, Self::DenyWithAlert)
    }

    /// Returns `true` if this decision requires an audit event to be emitted.
    #[must_use]
    pub fn requires_audit(self) -> bool {
        matches!(self, Self::DENY | Self::DenyWithAlert | Self::AllowWithLog)
    }
}

/// The trust level of the device the user is operating from.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "PascalCase")]
pub enum DeviceTrust {
    /// Device is managed by the organization (e.g., domain-joined, MDM-enrolled).
    Managed,
    /// Device is not managed by the organization.
    #[default]
    Unmanaged,
    /// Device meets the organization's compliance requirements.
    Compliant,
    /// Device trust level is unknown or indeterminate.
    Unknown,
}

/// Network location inferred from the client's IP address or VPN status.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "PascalCase")]
pub enum NetworkLocation {
    /// Device is on the corporate network (wired or wireless).
    Corporate,
    /// Device is connected via VPN.
    CorporateVpn,
    /// Device is on a guest or untrusted network.
    Guest,
    /// Location is unknown or could not be determined.
    #[default]
    Unknown,
}

/// The requesting user and their attributes.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct Subject {
    /// The user's Windows Security Identifier (e.g., "S-1-5-21-...").
    pub user_sid: String,
    /// The user's display name (e.g., "jsmith").
    pub user_name: String,
    /// The Windows Security Identifiers of all AD groups the user is a member of.
    pub groups: Vec<String>,
    /// The trust level of the device the user is operating from.
    #[serde(default)]
    pub device_trust: DeviceTrust,
    /// The network location of the device.
    #[serde(default)]
    pub network_location: NetworkLocation,
}

/// The file resource being accessed.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct Resource {
    /// The full path to the file or directory (e.g., "C:\\Data\\Q4-Financials.xlsx").
    pub path: String,
    /// The classification tier of the resource.
    pub classification: crate::Classification,
}

/// The environmental context at the time of the access request.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct Environment {
    /// The current time on the endpoint.
    pub timestamp: chrono::DateTime<chrono::Utc>,
    /// The session ID of the interactive session making the request.
    pub session_id: u32,
    /// Whether the request is originating from a remote SMB context.
    #[serde(default)]
    pub access_context: AccessContext,
}

/// Identity information about the requesting agent endpoint.
///
/// This is logged by the Policy Engine on every evaluation request to
/// identify which machine and user is making the request.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct AgentInfo {
    /// Machine hostname, e.g. "WORKSTATION-01".
    pub machine_name: Option<String>,
    /// The Windows username of the interactive session that triggered the request,
    /// e.g. "jsmith".
    pub current_user: Option<String>,
}

/// A complete ABAC evaluation request.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct EvaluateRequest {
    pub subject: Subject,
    pub resource: Resource,
    pub environment: Environment,
    pub action: Action,
    /// Agent endpoint identity — machine name and interactive user.
    /// Logged by the Policy Engine for request tracing.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub agent: Option<AgentInfo>,
    /// Resolved identity of the application that initiated the request
    /// (e.g. the process that copied clipboard content). Populated by
    /// Phase 25. `None` on requests from agents that predate Phase 25.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source_application: Option<AppIdentity>,
    /// Resolved identity of the destination application (e.g. the
    /// paste target). Populated by Phase 25.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub destination_application: Option<AppIdentity>,
    /// Source origin URL for browser clipboard events (e.g., the page where paste occurs).
    /// Populated by Phase 41 Chrome handler. `None` on requests from agents that predate Phase 41.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source_origin: Option<String>,
    /// Destination origin URL for browser clipboard events.
    /// Chrome Content Analysis API v1 does not expose this; always `None` in v0.8.0.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub destination_origin: Option<String>,
}

/// Internal ABAC evaluation context.
///
/// Constructed from [`EvaluateRequest`] at the evaluate boundary in Phase 26.
/// Mirrors [`EvaluateRequest`] fields minus wire-only metadata: there is
/// deliberately no `agent` field (per Phase 22 D-10) because `AgentInfo`
/// is request-tracing metadata, not an ABAC attribute.
///
/// Defined in Phase 22 so downstream crates compile against the type
/// before Phase 26 wires it into [`crate::abac::EvaluateRequest`]-to-context
/// conversion at `PolicyStore::evaluate()`.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct AbacContext {
    pub subject: Subject,
    pub resource: Resource,
    pub environment: Environment,
    pub action: Action,
    /// Resolved identity of the application that initiated the operation.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source_application: Option<AppIdentity>,
    /// Resolved identity of the destination application (paste target).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub destination_application: Option<AppIdentity>,
    /// Source origin URL for browser clipboard events.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source_origin: Option<String>,
    /// Destination origin URL for browser clipboard events.
    /// Chrome Content Analysis API v1 does not expose this; always `None` in v0.8.0.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub destination_origin: Option<String>,
}

/// A complete ABAC evaluation response.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EvaluateResponse {
    /// The enforcement decision.
    pub decision: Decision,
    /// The ID of the policy that matched (if any).
    pub matched_policy_id: Option<String>,
    /// A human-readable reason string for the decision.
    pub reason: String,
}

impl EvaluateResponse {
    /// Constructs a default-deny response for when no policy matches.
    pub fn default_deny() -> Self {
        Self {
            decision: Decision::DENY,
            matched_policy_id: None,
            reason: "No matching policy; default deny".to_string(),
        }
    }

    /// Constructs a permit response for when no policy matches and the system is
    /// configured for default-allow on non-sensitive resources.
    #[must_use]
    pub fn default_allow() -> Self {
        Self {
            decision: Decision::ALLOW,
            matched_policy_id: None,
            reason: "No matching policy; default allow".to_string(),
        }
    }
}

/// The application-identity field targeted by a [`PolicyCondition`].
///
/// Used with `SourceApplication` and `DestinationApplication` condition variants
/// to select which field of [`crate::endpoint::AppIdentity`] to compare.
///
/// # Serde
///
/// Serializes as snake_case: `"publisher"`, `"image_path"`, `"trust_tier"`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum AppField {
    /// Publisher common name from the Authenticode certificate (e.g., `"Microsoft Corporation"`).
    Publisher,
    /// Full NT image path of the process (e.g., `C:\Program Files\App\app.exe`).
    ImagePath,
    /// Application trust tier assigned by the Phase 25 publisher-verification pipeline.
    TrustTier,
    /// Application User Model ID (AUMID) for UWP apps (Phase 39).
    Aumid,
    /// Package Family Name for UWP apps (Phase 39).
    PackageFamilyName,
}

impl From<EvaluateRequest> for AbacContext {
    /// Converts a wire [`EvaluateRequest`] into an internal [`AbacContext`].
    ///
    /// The `agent` field is intentionally dropped — `AgentInfo` is
    /// request-tracing metadata, not an ABAC attribute (Phase 22 D-10).
    ///
    /// # Arguments
    ///
    /// * `req` - The wire-format evaluation request to convert.
    ///
    /// # Returns
    ///
    /// An [`AbacContext`] with `subject`, `resource`, `environment`, `action`,
    /// `source_application`, `destination_application`, `source_origin`, and
    /// `destination_origin` forwarded from `req`.
    fn from(req: EvaluateRequest) -> Self {
        Self {
            subject: req.subject,
            resource: req.resource,
            environment: req.environment,
            action: req.action,
            source_application: req.source_application,
            destination_application: req.destination_application,
            source_origin: req.source_origin,
            destination_origin: req.destination_origin,
        }
    }
}

/// A condition within an ABAC policy rule.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "attribute", rename_all = "snake_case")]
pub enum PolicyCondition {
    /// Match by resource classification tier.
    Classification {
        #[serde(rename = "op")]
        op: String,
        value: crate::Classification,
    },
    /// Match by AD group membership.
    MemberOf {
        #[serde(rename = "op")]
        op: String,
        group_sid: String,
    },
    /// Match by device trust level.
    DeviceTrust {
        #[serde(rename = "op")]
        op: String,
        value: DeviceTrust,
    },
    /// Match by network location.
    NetworkLocation {
        #[serde(rename = "op")]
        op: String,
        value: NetworkLocation,
    },
    /// Match by access context (local vs. SMB).
    AccessContext {
        #[serde(rename = "op")]
        op: String,
        value: AccessContext,
    },
    /// Match by the source application's identity (the process that initiated the operation).
    ///
    /// If `source_application` is `None` on the [`AbacContext`], this condition does NOT match
    /// (fails closed — no identity means the condition cannot be confirmed, per D-03).
    SourceApplication {
        /// Which field of [`crate::endpoint::AppIdentity`] to compare.
        field: AppField,
        /// Comparison operator: `"eq"`, `"ne"`, or `"contains"` (ImagePath only).
        #[serde(rename = "op")]
        op: String,
        /// The value to compare against (string form).
        value: String,
    },
    /// Match by the destination application's identity (the paste target process).
    ///
    /// If `destination_application` is `None` on the [`AbacContext`], this condition does NOT match
    /// (fails closed — no identity means the condition cannot be confirmed, per D-03).
    DestinationApplication {
        /// Which field of [`crate::endpoint::AppIdentity`] to compare.
        field: AppField,
        /// Comparison operator: `"eq"`, `"ne"`, or `"contains"` (ImagePath only).
        #[serde(rename = "op")]
        op: String,
        /// The value to compare against (string form).
        value: String,
    },
    /// Match by the source origin URL (the page where the clipboard paste is occurring).
    ///
    /// If `source_origin` is `None` on the [`AbacContext`], this condition does NOT match
    /// (fails closed — no origin means the condition cannot be confirmed, per D-03).
    SourceOrigin {
        /// Comparison operator: `"eq"`, `"ne"`, or `"contains"`.
        #[serde(rename = "op")]
        op: String,
        /// The origin string to compare against (e.g., `"https://sharepoint.com"`).
        value: String,
    },
    /// Match by the destination origin URL (the page where content is being pasted).
    ///
    /// If `destination_origin` is `None` on the [`AbacContext`], this condition does NOT match
    /// (fails closed — no origin means the condition cannot be confirmed, per D-03).
    DestinationOrigin {
        /// Comparison operator: `"eq"`, `"ne"`, or `"contains"`.
        #[serde(rename = "op")]
        op: String,
        /// The origin string to compare against (e.g., `"https://example.com"`).
        value: String,
    },
}

/// The boolean composition mode for a policy's condition list.
///
/// - `ALL`: every condition must match (implicit v0.4.0 behavior).
/// - `ANY`: at least one condition must match.
/// - `NONE`: no condition may match.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
pub enum PolicyMode {
    /// Every condition must match.
    #[default]
    ALL,
    /// At least one condition must match.
    ANY,
    /// No condition may match.
    NONE,
}

/// An ABAC policy rule.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct Policy {
    /// Unique identifier for this policy version.
    pub id: String,
    /// Human-readable name.
    pub name: String,
    /// Optional description.
    pub description: Option<String>,
    /// Relative priority — lower numbers are evaluated first; first-match wins.
    pub priority: u32,
    /// The conditions that must all be satisfied for this policy to match.
    pub conditions: Vec<PolicyCondition>,
    /// The system action to apply when this policy matches.
    pub action: Decision,
    /// Whether this policy is currently active.
    pub enabled: bool,
    /// Boolean composition mode for the conditions list.
    #[serde(default)]
    pub mode: PolicyMode,
    /// Monotonically increasing version number.
    pub version: u64,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_abac_context_default() {
        // Pitfall 1 prevention: AbacContext is public but not referenced in
        // library code during Phase 22 (Phase 26 wires it in). Constructing
        // the default here both prevents the dead_code warning and locks the
        // D-10 invariant: no `agent` field, both application fields None.
        let ctx = AbacContext::default();
        assert!(ctx.source_application.is_none());
        assert!(ctx.destination_application.is_none());
    }

    #[test]
    fn test_abac_context_round_trip() {
        use crate::endpoint::{AppIdentity, AppTrustTier, SignatureState};
        let ctx = AbacContext {
            source_application: Some(AppIdentity {
                image_path: r"C:\app.exe".to_string(),
                publisher: "Contoso".to_string(),
                trust_tier: AppTrustTier::Trusted,
                signature_state: SignatureState::Valid,
                aumid: None,
                package_family_name: None,
                is_uwp: false,
            }),
            ..Default::default()
        };
        let json = serde_json::to_string(&ctx).unwrap();
        let rt: AbacContext = serde_json::from_str(&json).unwrap();
        assert_eq!(
            rt.source_application.as_ref().map(|a| a.publisher.as_str()),
            Some("Contoso"),
        );
        assert!(rt.destination_application.is_none());
        // Destination app is None, so the key must be absent from JSON.
        assert!(!json.contains("destination_application"));
    }

    #[test]
    fn test_evaluate_request_app_identity_fields_round_trip() {
        use crate::endpoint::{AppIdentity, AppTrustTier, SignatureState};
        let req = EvaluateRequest {
            source_application: Some(AppIdentity {
                image_path: r"C:\src.exe".to_string(),
                publisher: "Adobe Inc.".to_string(),
                trust_tier: AppTrustTier::Trusted,
                signature_state: SignatureState::Valid,
                aumid: None,
                package_family_name: None,
                is_uwp: false,
            }),
            destination_application: Some(AppIdentity {
                image_path: r"C:\dst.exe".to_string(),
                publisher: "Unknown".to_string(),
                trust_tier: AppTrustTier::Untrusted,
                signature_state: SignatureState::NotSigned,
                aumid: None,
                package_family_name: None,
                is_uwp: false,
            }),
            ..Default::default()
        };
        let json = serde_json::to_string(&req).unwrap();
        let rt: EvaluateRequest = serde_json::from_str(&json).unwrap();
        assert_eq!(
            rt.source_application
                .as_ref()
                .map(|a| a.image_path.as_str()),
            Some(r"C:\src.exe"),
        );
        assert_eq!(
            rt.destination_application
                .as_ref()
                .map(|a| a.image_path.as_str()),
            Some(r"C:\dst.exe"),
        );
    }

    #[test]
    fn test_app_field_aumid_serde() {
        let json = serde_json::to_string(&AppField::Aumid).unwrap();
        assert_eq!(json, "\"aumid\"");
        let rt: AppField = serde_json::from_str("\"aumid\"").unwrap();
        assert_eq!(rt, AppField::Aumid);
    }

    #[test]
    fn test_app_field_package_family_name_serde() {
        let json = serde_json::to_string(&AppField::PackageFamilyName).unwrap();
        assert_eq!(json, "\"package_family_name\"");
        let rt: AppField = serde_json::from_str("\"package_family_name\"").unwrap();
        assert_eq!(rt, AppField::PackageFamilyName);
    }

    #[test]
    fn test_evaluate_request_omits_none_app_identity_fields() {
        // SC-3 observable truth: default EvaluateRequest serializes without
        // the two new keys when they are None, preserving wire-compat with
        // every agent running today (that does not send them).
        let req = EvaluateRequest::default();
        let json = serde_json::to_string(&req).unwrap();
        assert!(!json.contains("source_application"), "json was: {json}");
        assert!(
            !json.contains("destination_application"),
            "json was: {json}"
        );
    }

    #[test]
    fn test_evaluate_request_backward_compat_missing_new_fields() {
        // SC-3: old payloads without the two new fields must still deserialize.
        // This is the exact shape dlp-agent emits today.
        let old_payload = r#"{
            "subject": {},
            "resource": {},
            "environment": {},
            "action": "READ"
        }"#;
        let req: EvaluateRequest = serde_json::from_str(old_payload).unwrap();
        assert!(req.source_application.is_none());
        assert!(req.destination_application.is_none());
    }

    #[test]
    fn test_decision_is_denied() {
        assert!(!Decision::ALLOW.is_denied());
        assert!(Decision::DENY.is_denied());
        assert!(!Decision::AllowWithLog.is_denied());
